/** Turns a hole descriptor into renderable meshes backed by shared geometry and material caches. */
export class HoleSceneBuilder {
  private readonly boxGeometry: THREE.BoxGeometry;
  private readonly cylinderGeometry: THREE.CylinderGeometry;
  private readonly materials: Map<string, THREE.MeshStandardMaterial>;

  constructor() {
    this.boxGeometry = new THREE.BoxGeometry(1, 1, 1);
    this.cylinderGeometry = new THREE.CylinderGeometry(0.5, 0.5, 1, 24);
    this.materials = new Map();
  }

  build(hole: Hole): HoleSceneResult {
    const group = new THREE.Group();
    group.name = hole.id;

    for (const surface of hole.surfaces) {
      group.add(this.buildSurface(surface));
    }
    for (const obstacle of hole.obstacles) {
      group.add(this.buildObstacle(obstacle, hole));
    }
    group.add(this.buildCup(hole));

    return {
      group,
      meshCount: group.children.length,
      dispose: () => {
        group.clear();
      },
    };
  }

  dispose(): void {
    this.boxGeometry.dispose();
    this.cylinderGeometry.dispose();
    for (const material of this.materials.values()) {
      material.dispose();
    }
    this.materials.clear();
  }

  private buildSurface(surface: SurfaceDescriptor): THREE.Mesh {
    const geometry = surface.shape === 'cylinder' ? this.cylinderGeometry : this.boxGeometry;
    const mesh = new THREE.Mesh(
      geometry,
      this.materialFor('surface:' + surface.material, SURFACE_COLORS[surface.material]),
    );
    mesh.name = surface.id;
    applyTransform(mesh, surface.transform, surface.size);
    mesh.castShadow = false;
    mesh.receiveShadow = true;
    return mesh;
  }

  private buildObstacle(obstacle: ObstacleDescriptor, hole: Hole): THREE.Mesh {
    if (HAZARD_TYPES.has(obstacle.type)) {
      return this.buildHazard(obstacle, hole);
    }
    if (FIELD_TYPES.has(obstacle.type)) {
      return this.buildField(obstacle);
    }
    const geometry = obstacle.type === 'pillar' ? this.cylinderGeometry : this.boxGeometry;
    const mesh = new THREE.Mesh(
      geometry,
      this.materialFor('obstacle:' + obstacle.type, OBSTACLE_COLORS[obstacle.type]),
    );
    mesh.name = obstacle.id;
    applyTransform(mesh, obstacle.transform, obstacle.size);
    mesh.castShadow = true;
    mesh.visible = obstacle.enabled !== false;
    return mesh;
  }

  /** Flat emissive spill laid on the course; the collider height stays invisible. */
  private buildHazard(obstacle: ObstacleDescriptor, hole: Hole): THREE.Mesh {
    const mesh = new THREE.Mesh(
      this.boxGeometry,
      this.sensorMaterialFor('hazard:' + obstacle.type, OBSTACLE_COLORS[obstacle.type], HAZARD_OPACITY, false),
    );
    mesh.name = obstacle.id;
    const size = scaledSize(obstacle);
    const position = obstacle.transform.position;
    const top = hazardSurfaceTop(hole, obstacle);
    mesh.position.set(position.x, top + HAZARD_SLAB_LIFT + HAZARD_SLAB_HEIGHT / 2, position.z);
    const rotation = obstacle.transform.rotation;
    if (rotation) {
      mesh.quaternion.set(rotation.x, rotation.y, rotation.z, rotation.w);
    }
    mesh.scale.set(size.x, HAZARD_SLAB_HEIGHT, size.z);
    mesh.castShadow = false;
    mesh.receiveShadow = false;
    mesh.visible = obstacle.enabled !== false;
    return mesh;
  }

  /** Force fields keep their volume so the reach stays readable, but stay a see-through haze. */
  private buildField(obstacle: ObstacleDescriptor): THREE.Mesh {
    const mesh = new THREE.Mesh(
      this.boxGeometry,
      this.sensorMaterialFor('field:' + obstacle.type, OBSTACLE_COLORS[obstacle.type], FIELD_OPACITY, true),
    );
    mesh.name = obstacle.id;
    applyTransform(mesh, obstacle.transform, obstacle.size);
    mesh.castShadow = false;
    mesh.receiveShadow = false;
    mesh.visible = obstacle.enabled !== false;
    return mesh;
  }

  private buildCup(hole: Hole): THREE.Mesh {
    const mesh = new THREE.Mesh(this.cylinderGeometry, this.materialFor('cup', CUP_COLOR));
    mesh.name = hole.id + '-cup';
    const diameter = hole.cup.radius * 2;
    mesh.position.set(hole.cup.position.x, hole.cup.position.y, hole.cup.position.z);
    mesh.scale.set(diameter, hole.cup.radius, diameter);
    mesh.castShadow = false;
    mesh.receiveShadow = true;
    return mesh;
  }

  private materialFor(key: string, color: number): THREE.MeshStandardMaterial {
    const cached = this.materials.get(key);
    if (cached) {
      return cached;
    }
    const material = new THREE.MeshStandardMaterial({ color, roughness: 0.85, metalness: 0.05 });
    material.name = key;
    this.materials.set(key, material);
    return material;
  }

  private sensorMaterialFor(
    key: string,
    color: number,
    opacity: number,
    doubleSided: boolean,
  ): THREE.MeshStandardMaterial {
    const cached = this.materials.get(key);
    if (cached) {
      return cached;
    }
    const material = new THREE.MeshStandardMaterial({
      color,
      roughness: 0.35,
      metalness: 0,
      emissive: color,
      emissiveIntensity: SENSOR_EMISSIVE_INTENSITY,
      transparent: true,
      opacity,
      depthWrite: false,
      side: doubleSided ? THREE.DoubleSide : THREE.FrontSide,
    });
    material.name = key;
    this.materials.set(key, material);
    return material;
  }
}
