function makeHole(): Hole {
  return {
    id: 'hazard-hole',
    name: 'Hazard Hole',
    par: 3,
    spawn: { x: 0, y: 0.65, z: -11 },
    cup: { position: { x: 2, y: 0.25, z: 11 }, radius: 0.55, captureDepth: 0.45 },
